#!/bin/bash
# Uninstall script for Nota Gyazo GIF
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Nota Gyazo GIF..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Nota Gyazo GIF if running..."
pkill -f "Nota Gyazo GIF" 2>/dev/null || true

# Unload service com.gyazo.menu.helper
echo "Unloading service com.gyazo.menu.helper..."
launchctl unload -w /Library/LaunchAgents/com.gyazo.menu.helper.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/com.gyazo.menu.helper.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/com.gyazo.menu.helper.plist 2>/dev/null || true

# Kill application with bundle ID com.gyazo.menu if running
echo "Stopping application with bundle ID com.gyazo.menu if running..."
killall -9 "com.gyazo.menu" 2>/dev/null || true

# Remove $HOME/Library/Caches/com.gyazo.gif
echo "Removing $HOME/Library/Caches/com.gyazo.gif..."
if [ -d "$HOME/Library/Caches/com.gyazo.gif" ]; then
    rm -rf "$HOME/Library/Caches/com.gyazo.gif" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/com.gyazo.gif" ]; then
    rm -f "$HOME/Library/Caches/com.gyazo.gif" 2>/dev/null || true
fi

# Remove $HOME/Library/Caches/com.gyazo.mac
echo "Removing $HOME/Library/Caches/com.gyazo.mac..."
if [ -d "$HOME/Library/Caches/com.gyazo.mac" ]; then
    rm -rf "$HOME/Library/Caches/com.gyazo.mac" 2>/dev/null || true
elif [ -f "$HOME/Library/Caches/com.gyazo.mac" ]; then
    rm -f "$HOME/Library/Caches/com.gyazo.mac" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.gyazo.gif.plist
echo "Removing $HOME/Library/Preferences/com.gyazo.gif.plist..."
if [ -d "$HOME/Library/Preferences/com.gyazo.gif.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.gyazo.gif.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.gyazo.gif.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.gyazo.gif.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/com.gyazo.mac.plist
echo "Removing $HOME/Library/Preferences/com.gyazo.mac.plist..."
if [ -d "$HOME/Library/Preferences/com.gyazo.mac.plist" ]; then
    rm -rf "$HOME/Library/Preferences/com.gyazo.mac.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/com.gyazo.mac.plist" ]; then
    rm -f "$HOME/Library/Preferences/com.gyazo.mac.plist" 2>/dev/null || true
fi

